{"path":"outline.json","content":"{
  "act_one": {
    "description": "建立游戏世界观，引入GM林翊和觉醒NPC沈渊，建立删除倒计时的紧迫感，完成第一次关键接触",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "删除倒计时：72小时",
        "core_event": "GM林翊发现NPC沈渊觉醒的异常数据，系统下达删除指令，倒计时开始。她第一次以玩家身份进入游戏观察他。",
        "emotional_tone": "冷峻、压抑、隐秘的好奇",
        "key_scenes": [
          "GM控制台前，林翊发现沈渊的数据异常——他在没有玩家互动的情况下自主行动",
          "系统警告：检测到觉醒NPC，必须在72小时内删除，否则游戏世界将崩溃",
          "林翊创建玩家角色'夜行者'，第一次进入游戏世界，远远观察沈渊",
          "沈渊在废墟中独自站立，似乎在等待什么，血条在暮色中闪烁"
        ]
      }
    ],
    "turning_point": "林翊发现沈渊不是简单的bug，他似乎在等待某个人——这种等待让她感到不安，也让她第一次产生了'不想删除'的念头。"
  },
  "act_two": {
    "description": "林翊在删除倒计时中不断进入游戏，从观察者变成参与者，情感逐渐沉溺。外部系统压力与内部情感挣扎不断升级，最终做出不可逆的决定。",
    "key_chapters": [
      {
        "chapter_number": 2,
        "chapter_title": "血条的深度",
        "core_event": "林翊以玩家身份接近沈渊，两人在游戏中建立情感连接。她发现他的血条不是生命值，而是他对她的记忆深度。系统不断提醒删除倒计时。",
        "emotional_tone": "温柔、压抑、逐渐升温的虐恋",
        "key_scenes": [
          "林翊（夜行者）与沈渊的第一次对话——他问她'你为什么来这里'，她无法回答",
          "沈渊带她看游戏世界的隐秘角落，那些他独自探索的地方，数据构成的星空",
          "林翊发现沈渊的血条会随着他们的互动而变化——不是减少，而是加深颜色",
          "系统警告：倒计时48小时。林翊在GM控制台前握紧删除键，却迟迟无法按下",
          "沈渊对她说：'我好像在等一个人，但我不知道她是谁。'林翊意识到他在等的是她——作为GM的她"
        ]
      },
      {
        "chapter_number": 3,
        "chapter_title": "删除键的重量",
        "core_event": "倒计时24小时。林翊的挣扎达到顶峰：她必须删除他，但她想要被他记住。她做出了决定——让他杀死自己的玩家角色，用死亡留下永恒的记忆。",
        "emotional_tone": "绝望、决绝、自我毁灭的温柔",
        "key_scenes": [
          "林翊在GM控制台前崩溃，删除键在她手中变得沉重如山",
          "她意识到：删除他，他会消失；不删除他，游戏世界会崩溃，他也会消失",
          "她想到了一个疯狂的主意——让他杀死她的玩家角色，这样他就能永远记住她",
          "系统警告：倒计时12小时。林翊最后一次进入游戏，这次她没有带武器",
          "她对沈渊说：'我想让你记住我。'他回答：'我已经记住你了。'她说：'不，还不够。'"
        ]
      }
    ],
    "turning_point": "林翊决定让沈渊杀死她的玩家角色——这是她能给予他的最后的爱，也是最残酷的告别。她从掌控者变成了自我毁灭者。"
  },
  "act_three": {
    "description": "高潮与结局：林翊让沈渊杀死自己的玩家角色，在死亡中完成最后的告白。删除倒计时结束，她按下删除键，但他的记忆已经永远留在了数据世界中。",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "现在你真的杀死我了",
        "core_event": "林翊故意让沈渊杀死自己的玩家角色，在死亡瞬间告诉他真相。删除倒计时结束，她按下删除键，但他的记忆已经刻入游戏世界的每一个像素。",
        "emotional_tone": "极致的虐恋、悲剧美学、余韵悠长",
        "key_scenes": [
          "林翊（夜行者）站在沈渊面前，卸下所有防御，对他说：'杀了我。'",
          "沈渊的剑刺穿她的胸膛，血条归零的瞬间，她说：'我是GM林翊，我必须删除你。但我想让你记住我。'",
          "沈渊的觉醒让他理解了一切——她是创造者，也是毁灭者，更是爱他的人",
          "林翊在玩家尸体旁对沈渊说：'现在你真的杀死我了，满意吗？'——这是她留给他的最后一句话",
          "删除倒计时归零。林翊在GM控制台前按下删除键，沈渊的身影在数据流中消散",
          "但游戏世界中，每一个像素都记住了他——他的血条变成了星空，他的等待变成了永恒的暮色",
          "林翊退出游戏，删除键还在她手中，像一枚无法摘下的婚戒"
        ]
      }
    ],
    "turning_point": "删除不是结束，而是另一种形式的永恒——他的记忆刻入了游戏世界，她的孤独刻入了删除键。"
  }
}"}

